// Transparent, rule-based lead scoring. 0-100.
//
// This is deliberately NOT an LLM call. A score that routes revenue has to be
// auditable ("why was this a 65?"), free, and instant. Every point below is
// traceable to a rule you can argue with in a sales meeting.
//
// Thresholds consumed by the Switch node downstream:
//   >= 70  hot      -> notify sales in real time + upsert to CRM
//   40-69  nurture  -> drip sequence, no human touch yet
//   <  40  log only -> stored for reporting, nobody is paged

const FREEMAIL = new Set([
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'aol.com',
  'icloud.com', 'me.com', 'live.com', 'msn.com', 'proton.me', 'protonmail.com',
  'gmx.com', 'mail.com', 'yandex.com', 'zoho.com',
]);

const ROLE_PREFIXES = new Set([
  'info', 'sales', 'support', 'admin', 'contact', 'hello', 'noreply', 'no-reply',
  'billing', 'webmaster', 'postmaster',
]);

const out = [];

for (const item of $input.all()) {
  const lead = item.json;
  const reasons = [];
  let score = 0;

  const email = (lead.email || '').toLowerCase();
  const domain = (lead.email_domain || '').toLowerCase();
  const localPart = email.split('@')[0] || '';

  // --- Email quality (max 40) ---------------------------------------------
  // A business domain is the single strongest cheap signal that this is a real
  // buyer and not someone kicking tires from a personal address.
  const looksLikeEmail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
  if (!looksLikeEmail) {
    reasons.push('email is malformed (-)');
  } else if (domain && !FREEMAIL.has(domain)) {
    score += 40;
    reasons.push('business email domain (+40)');
  } else {
    score += 10;
    reasons.push('freemail domain (+10)');
  }

  // A role address means no named human owns the conversation yet.
  if (ROLE_PREFIXES.has(localPart)) {
    score -= 10;
    reasons.push('role address, not a person (-10)');
  }

  // --- Company named (max 15) ---------------------------------------------
  if ((lead.company || '').length >= 2) {
    score += 15;
    reasons.push('company provided (+15)');
  }

  // --- Message intent (max 25) --------------------------------------------
  // Length is a crude proxy for effort, and effort correlates with intent.
  // Someone who typed three paragraphs has a problem they want solved.
  const msg = lead.message || '';
  if (msg.length >= 300) {
    score += 25;
    reasons.push('detailed message, 300+ chars (+25)');
  } else if (msg.length >= 80) {
    score += 15;
    reasons.push('substantive message, 80+ chars (+15)');
  } else if (msg.length > 0) {
    score += 5;
    reasons.push('short message (+5)');
  }

  // --- Enrichment (max 20) -------------------------------------------------
  // Only additive. A lead is never punished for the enrichment vendor being
  // down, which is why the fallback branch sets enriched=false rather than
  // failing the execution.
  if (lead.enriched === true) {
    score += 10;
    reasons.push('enrichment matched (+10)');

    const size = Number(lead.company_size);
    if (Number.isFinite(size) && size >= 50) {
      score += 10;
      reasons.push(`company size ${size} (+10)`);
    }
  } else {
    reasons.push('no enrichment data (+0)');
  }

  score = Math.max(0, Math.min(100, score));

  const band = score >= 70 ? 'hot' : score >= 40 ? 'nurture' : 'log';

  out.push({
    json: {
      ...lead,
      score,
      band,
      // Shipped with the record on purpose: when sales asks why a lead was not
      // routed to them, the answer is already attached to the lead.
      score_reasons: reasons,
    },
  });
}

return out;
